insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 31, 'Mas as casas das aldeias que não têm muro ao redor, serão estimadas como uma plantação da terra: terão remissão, e sairão no jubileu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 32, 'Porém em quanto às cidades dos levitas, sempre poderão resgatar os levitas as casas das cidades que possuírem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 33, 'E o que comprar dos levitas, sairá da casa vendida, ou da cidade de sua possessão, no jubileu: porquanto as casas das cidades dos levitas é a possessão deles entre os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 34, 'Mas a terra dos arredores de suas cidades não se venderá, porque é perpétua possessão deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 35, 'E quando teu irmão empobrecer, e se refugiar a ti, tu o ampararás: como peregrino e estrangeiro viverá contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 36, 'Não tomarás juros dele, nem lucro; mas terás temor de teu Deus, e teu irmão viverá contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 37, 'Não lhe darás teu dinheiro a juros, nem tua comida a ganho:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 38, 'Eu sou o SENHOR vosso Deus, que vos tirei da terra do Egito, para vos dar a terra de Canaã, para ser vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 39, 'E quando teu irmão empobrecer, estando contigo, e se vender a ti, não lhe farás servir como servo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 40, 'Como criado, como estrangeiro estará contigo; até o ano do jubileu te servirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 41, 'Então sairá de tua presença, ele e seus filhos consigo, e voltará à sua família, e à possessão de seus pais se restituirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 42, 'Porque são meus servos, os quais tirei eu da terra do Egito: não serão vendidos à maneira de servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 43, 'Não serás senhor dele com dureza, mas terás temor de teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 44, 'Assim teu servo como tua serva que tiveres, serão das nações que estão em vosso ao redor: deles comprareis servos e servas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 45, 'Também comprareis dos filhos dos forasteiros que vivem entre vós, e dos que da linhagem deles são nascidos em vossa terra, que estão convosco; os quais tereis por possessão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 46, 'E os possuireis por herança para vossos filhos depois de vós, como possessão hereditária; para sempre vos servireis deles; porém em vossos irmãos os filhos de Israel, não vos dominareis cada um sobre seu irmão com dureza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 47, 'E se o peregrino ou estrangeiro que está contigo, adquirisse meios, e teu irmão que está com ele empobrecer, e se vender ao peregrino ou estrangeiro que está contigo, ou à raça da família do estrangeiro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 48, 'Depois que se houver vendido, poderá ser resgatado: um de seus irmãos o resgatará;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 49, 'Ou seu tio, ou o filho de seu tio o resgatará, ou o próximo de sua carne, de sua linhagem, o resgatará; ou se seus meios alcançarem, ele mesmo se resgatará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 50, 'E contará com o que o comprou, desde o ano que se vendeu a ele até o ano do jubileu: e há de estabelecer preço o dinheiro de sua venda conforme o número dos anos, e se fará com ele conforme o tempo de um criado assalariado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 51, 'Se ainda forem muitos anos, conforme eles voltará para seu resgate do dinheiro pelo qual se vendeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 52, 'E se restar pouco tempo até o ano do jubileu, então contará com ele, e devolverá seu resgate conforme seus anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 53, 'Como com tomado a salário anualmente fará com ele: não será senhor dele com aspereza diante de teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 54, 'Mas se não se resgatar em esses anos, no ano do jubileu sairá, ele, e seus filhos com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 55, 'Porque meus servos são os filhos de Israel; são servos meus, aos quais tirei da terra do Egito: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 1, 'Não fareis para vós ídolos, nem escultura, nem levantareis para vós estátua, nem poreis em vossa terra pedra pintada para inclinar-vos a ela: porque eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 2, 'Guardai meus sábados, e tende em reverência meu santuário: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 3, 'Se andardes em meus decretos, e guardardes meus mandamentos, e os puserdes por obra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 4, 'Eu darei vossa chuva em seu tempo, e a terra produzirá, e a árvore do campo dará seu fruto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 5, 'E a debulha vos alcançará à vindima, e a vindima alcançará à sementeira, e comereis vosso pão em fartura e habitareis seguros em vossa terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 6, 'E eu darei paz na terra, e dormireis, e não haverá quem vos espante; e farei tirar os animais ferozes de vossa terra, e a espada não passará por vossa terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 7, 'E perseguireis aos vossos inimigos, e cairão à espada diante de vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 8, 'E cinco de vós perseguirão a cem, e cem de vós perseguirão a dez mil, e vossos inimigos cairão à espada diante de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 9, 'Porque eu me voltarei a vós, e vos farei crescer, e vos multiplicarei, e afirmarei meu pacto convosco:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 10, 'E comereis o antigo de muito tempo, e tirareis fora o antigo por causa do novo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 11, 'E porei minha morada em meio de vós, e minha alma não vos abominará:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 12, 'E andarei entre vós, e eu serei vosso Deus, e vós sereis meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 13, 'Eu sou o SENHOR vosso Deus, que vos tirei da terra do Egito, para que não fôsseis seus servos; e rompi as barras de vosso jugo, e vos fiz andar com o rosto alto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 14, 'Porém se não me ouvirdes, nem fizerdes todos estes meus mandamentos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 15, 'E se abominardes meus decretos, e vossa alma menosprezar meus regulamentos, não executando todos meus mandamentos, e invalidando meu pacto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 16, 'Eu também farei convosco isto: enviarei sobre vós terror, enfermidade e febre, que consumam os olhos e atormentem a alma: e semeareis em vão vossa semente, porque vossos inimigos a comerão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 17, 'E porei minha ira sobre vós, e sereis feridos diante de vossos inimigos; e os que vos aborrecem vos dominarão, e fugireis sem que haja quem vos persiga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 18, 'E se ainda com estas coisas não me ouvirdes, eu voltarei a castigar-vos sete vezes mais por vossos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 19, 'E quebrarei a soberba de vossa força, e voltarei vosso céu como ferro, e vossa terra como bronze:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 20, 'E vossa força se consumirá em vão; que vossa terra não dará seu produto, e as árvores da terra não darão seu fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 21, 'E se andardes comigo em oposição, e não me quiserdes ouvir, eu acrescentarei sobre vós sete vezes mais pragas segundo vossos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 22, 'Enviarei também contra vós animais feras que vos arrebatem os filhos, e destruam vossos animais, e vos reduzam a poucos, e vossos caminhos sejam desertos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 23, 'E se com estas coisas não fordes corrigidos, mas que andardes comigo em oposição,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 24, 'Eu também procederei convosco, em oposição e vos ferirei ainda sete vezes por vossos pecados:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 25, 'E trarei sobre vós espada vingadora, em castigo do pacto; e vos recolhereis a vossas cidades; mas eu enviarei pestilência entre vós, e sereis entregues em mão do inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 26, 'Quando eu vos quebrantar o sustento de pão, cozerão dez mulheres vosso pão em um forno, e vos devolverão vosso pão por peso; e comereis, e não vos fartareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 27, 'E se com isto não me ouvirdes, mas procederdes comigo em oposição,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 28, 'Eu procederei convosco em contra e com ira, e vos castigarei ainda sete vezes por vossos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 29, 'E comereis as carnes de vossos filhos, e comereis as carnes de vossas filhas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 30, 'E destruirei vossos altos, e exterminarei vossas imagens, e porei vossos corpos mortos sobre os corpos mortos de vossos ídolos, e meu alma vos abominará:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 31, 'E porei vossas cidades em deserto, e assolarei vossos santuários, e não cheirarei a fragrância de vosso suave incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 32, 'Eu assolarei também a terra, e se pasmarão dela vossos inimigos que nela moram:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 33, 'E a vós vos espalharei pelas nações, e desembainharei espada atrás de vós: e vossa terra estará assolada, e desertas vossas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 34, 'Então a terra folgará seus sábados todos os dias que estiver assolada, e vós na terra de vossos inimigos: a terra descansará então e desfrutará seus sábados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 35, 'Todo o tempo que estará assolada, folgará o que não folgou em vossos sábados enquanto habitáveis nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 36, 'E aos que restarem de vós porei em seus corações tal covardia, na terra de seus inimigos, que o som de uma folha movida os perseguirá, e fugirão como de espada, e cairão sem que ninguém os persiga:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 37, 'E tropeçarão uns nos outros, como se fugissem diante de espada, ainda que ninguém os persiga; e não podereis resistir diante de vossos inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 38, 'E perecereis entre as nações, e a terra de vossos inimigos vos consumirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 39, 'E os que restarem de vós perecerão nas terras de vossos inimigos por sua iniquidade; e pela iniquidade de seus pais perecerão com eles:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 40, 'E confessarão sua iniquidade, e a iniquidade de seus pais, por sua transgressão com que transgrediram contra mim: e também porque andaram comigo em oposição,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 41, 'Eu também houver andado contrário a eles, e os houver metido na terra de seus inimigos: e então se humilhará seu coração incircunciso, e reconhecerão seu pecado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 42, 'E eu me lembrarei de meu pacto com Jacó, e também de meu pacto com Isaque, e também de meu pacto com Abraão me lembrarei; e farei memória da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 43, 'Que a terra estará desamparada deles, e folgará seus sábados, estando deserta por causa deles; mas entretanto se submeterão ao castigo de suas iniquidades: porquanto menosprezaram meus regulamentos, e teve a alma deles ódio de meus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 44, 'E ainda com tudo isto, estando eles em terra de seus inimigos, eu não os rejeitarei, nem os abominarei para consumi-los, invalidando meu pacto com eles: porque eu o SENHOR sou seu Deus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 45, 'Antes me lembrarei deles pelo pacto antigo, quando os tirei da terra do Egito aos olhos das nações, para ser seu Deus: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 26, 46, 'Estes são os decretos, regulamentos e leis que estabeleceu o SENHOR entre si e os filhos de Israel no monte Sinai por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando alguém fizer especial voto ao SENHOR, segundo a avaliação das pessoas que se hajam de resgatar, assim será tua avaliação:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 3, 'Em quanto ao homem de vinte anos até sessenta, tua avaliação será cinquenta siclos de prata, segundo o siclo do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 4, 'E se for fêmea, a avaliação será trinta siclos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 5, 'E se for de cinco anos até vinte, tua avaliação será respeito ao homem vinte siclos, e à fêmea dez siclos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 6, 'E se for de um mês até cinco anos, tua avaliação será em ordem ao homem, cinco siclos de prata; e pela fêmea será tua avaliação três siclos de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 7, 'Mas se for de sessenta anos acima, pelo homem tua avaliação será quinze siclos, e pela fêmea dez siclos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 8, 'Porém se for mais pobre que tua avaliação, então comparecerá ante o sacerdote, e o sacerdote lhe porá valor: conforme a capacidade do votante lhe imporá valor o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 9, 'E se for animal de que se oferece oferta ao SENHOR, tudo o que se der dele ao SENHOR será santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 10, 'Não será mudado nem trocado, bom por mau, nem mau por bom; e se se permutar um animal por outro, ele e o dado por ele em troca serão sagrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 11, 'E se for algum animal impuro, de que não se oferece oferta ao SENHOR, então o animal será posto diante do sacerdote:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 12, 'E o sacerdote o avaliará preço, seja bom ou seja mau; conforme a avaliação do sacerdote, assim será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 13, 'E se o houverem de resgatar, acrescentarão seu quinto sobre tua avaliação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 14, 'E quando alguém santificar sua casa consagrando-a ao SENHOR, a avaliará preço o sacerdote, seja boa ou seja má: segundo a avaliar o sacerdote, assim ficará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 15, 'Mas se o que a santificar resgatar sua casa, acrescentará à tua avaliação o quinto do dinheiro dela, e será sua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 16, 'E se alguém santificar da terra de sua possessão ao SENHOR, tua avaliação será conforme sua semeadura: um ômer de semeadura de cevada se avaliará preço em cinquenta siclos de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 17, 'E se santificar sua terra desde o ano do jubileu, conforme tua avaliação ficará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 18, 'Mas se depois do jubileu santificar sua terra, então o sacerdote fará a conta do dinheiro conforme os anos que restarem até o ano do jubileu, e se diminuirá de tua avaliação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 19, 'E se o que santificou a terra quiser resgatá-la, acrescentará à tua avaliação o quinto do dinheiro dela, e ficará para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 20, 'Mas se ele não resgatar a terra, e a terra se vender a outro, não a resgatará mais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 21, 'Em vez disso quando sair no jubileu, a terra será santa ao SENHOR, como terra consagrada: a possessão dela será do sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 22, 'E se santificar alguém ao SENHOR a terra que ele comprou, que não era da terra de sua herança,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 23, 'Então o sacerdote calculará com ele a soma de tua avaliação até o ano do jubileu, e aquele dia dará teu assinalado preço, coisa consagrada ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 24, 'No ano do jubileu, voltará a terra a aquele de quem ele a comprou, cuja é a herança da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 25, 'E tudo o que avaliares o preço será conforme o siclo do santuário: o siclo tem vinte óbolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 26, 'Porém o primogênito dos animais, que pela primogenitura é do SENHOR, ninguém o santificará; seja boi ou ovelha, do SENHOR é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 27, 'Mas se for dos animais impuros, o resgatarão conforme tua avaliação, e acrescentarão sobre ela seu quinto: e se não o resgatarem, se venderá conforme tua avaliação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 28, 'Porém nenhuma coisa consagrada, que alguém houver santificado ao SENHOR de tudo o que tiver, de homens e animais, e das terras de sua possessão, não se venderá, nem se resgatará: todo o consagrado será coisa santíssima ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 29, 'Qualquer um que for consagrado dentre o homens que for separado para a condenação não será resgatado; inevitavelmente será morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 30, 'E todos os dízimos da terra, tanto das sementes da terra como dos frutos das árvores, pertencem ao SENHOR; são coisas consagradas ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 31, 'E se alguém quiser resgatar algo de seus dízimos, acrescentará seu quinto a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 32, 'E todo dízimo de vacas ou de ovelhas, de tudo o que passa sob a vara, a décima parte será consagrada ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 33, 'Não olhará se é bom ou mau, nem o trocará; e se o trocar, ele e o seu trocado serão consagrados; não se resgatará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 27, 34, 'Esses são os mandamentos que o SENHOR ordenou a Moisés para os filhos de Israel, no monte Sinai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 1, 'E o SENHOR falou a Moisés no deserto de Sinai, no tabernáculo do testemunho, no primeiro dia do mês segundo, no segundo ano de sua saída da terra do Egito, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 2, 'Tomai o censo de toda a congregação dos filhos de Israel por suas famílias, pelas casas de seus pais, com a conta dos nomes, todos os homens por suas cabeças:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 3, 'De vinte anos acima, todos os que podem sair à guerra em Israel, os contareis tu e Arão por suas tropas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 4, 'E estará convosco um homem de cada tribo, cada um chefe da casa de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 5, 'E estes são os nomes dos homens que estarão convosco: Da tribo de Rúben, Elizur filho de Sedeur.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 6, 'De Simeão, Selumiel filho de Zurisadai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 7, 'De Judá, Naassom filho de Aminadabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 8, 'De Issacar, Natanael filho de Zuar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 9, 'De Zebulom, Eliabe filho de Helom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 10, 'Dos filhos de José: de Efraim, Elisama filho de Amiúde; de Manassés, Gamaliel filho de Pedazur.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 11, 'De Benjamim, Abidã filho de Gideoni.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 12, 'De Dã, Aiezer filho de Amisadai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 13, 'De Aser, Pagiel filho de Ocrã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 14, 'De Gade, Eliasafe filho de Deuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 15, 'De Naftali, Aira filho de Enã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 16, 'Estes foram os nomeados da congregação, príncipes das tribos de seus pais, capitães dos milhares de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 17, 'Tomou pois Moisés e Arão a estes homens que foram declarados por seus nomes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 18, 'E juntaram toda a congregação no primeiro dia do mês segundo, e foram reunidos suas linhagens, pelas casas de seus pais, segundo a conta dos nomes, de vinte anos acima, por suas cabeças,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 19, 'Como o SENHOR o havia mandado a Moisés; e contou-os no deserto de Sinai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 20, 'E os filhos de Rúben, primogênito de Israel, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes por suas cabeças, todos os homens de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 21, 'Os contados deles, da tribo de Rúben, foram quarenta e seis mil e quinhentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 22, 'Dos filhos de Simeão, por suas gerações, por suas famílias, pelas casas de seus pais, os contados deles conforme a conta dos nomes por suas cabeças, todos os homens de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 23, 'Os contados deles, da tribo de Simeão, cinquenta e nove mil e trezentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 24, 'Dos filhos de Gade, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 25, 'Os contados deles, da tribo de Gade, quarenta e cinco mil seiscentos e cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 26, 'Dos filhos de Judá, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 27, 'Os contados deles, da tribo de Judá, setenta e quatro mil e seiscentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 28, 'Dos filhos de Issacar, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 29, 'Os contados deles, da tribo de Issacar, cinquenta e quatro mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 30, 'Dos filhos de Zebulom, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta de seus nomes, de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 31, 'Os contados deles, da tribo de Zebulom, cinquenta e sete mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 32, 'Dos filhos de José: dos filhos de Efraim, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 33, 'Os contados deles, da tribo de Efraim, quarenta mil e quinhentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 34, 'Dos filhos de Manassés, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 35, 'Os contados deles, da tribo de Manassés, trinta e dois mil e duzentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 36, 'Dos filhos de Benjamim, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 37, 'Os contados deles, da tribo de Benjamim, trinta e cinco mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 38, 'Dos filhos de Dã, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 39, 'Os contados deles, da tribo de Dã, sessenta e dois mil e setecentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 40, 'Dos filhos de Aser, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 41, 'Os contados deles, da tribo de Aser, quarenta e um mil e quinhentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 42, 'Dos filhos de Naftali, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 43, 'Os contados deles, da tribo de Naftali, cinquenta e três mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 44, 'Estes foram os contados, os quais contaram Moisés e Arão, com os príncipes de Israel, que eram doze, um por cada casa de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 45, 'E foram todos os contados dos filhos de Israel pelas casas de seus pais, de vinte anos acima, todos os que podiam sair à guerra em Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 46, 'Foram todos os contados seiscentos três mil quinhentos e cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 47, 'Porém os levitas não foram contados entre eles segundo a tribo de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 48, 'Porque falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 49, 'Somente não contarás a tribo de Levi, nem tomarás a conta deles entre os filhos de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 50, 'Mas tu porás aos levitas no tabernáculo do testemunho, e sobre todos os seus utensílios, e sobre todas as coisas que lhe pertencem: eles levarão o tabernáculo e todos os seus utensílios, e eles servirão nele, e assentarão suas tendas ao redor do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 51, 'E quando o tabernáculo partir, os levitas o desarmarão; e quando o tabernáculo parar, os levitas o armarão: e o estranho que se chegar, morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 52, 'E os filhos de Israel assentarão suas tendas cada um em seu esquadrão, e cada um junto à sua bandeira, por suas tropas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 53, 'Mas os levitas assentarão as suas ao redor do tabernáculo do testemunho, e não haverá ira sobre a congregação dos filhos de Israel: e os levitas terão a guarda do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 1, 54, 'E fizeram os filhos de Israel conforme todas as coisas que mandou o SENHOR a Moisés; assim o fizeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 2, 'Os filhos de Israel acamparão cada um junto à sua bandeira, segundo as insígnias das casas de seus pais; ao redor do tabernáculo do testemunho acamparão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 3, 'Estes acamparão ao levante, ao oriente: a bandeira do exército de Judá, por seus esquadrões; e o chefe dos filhos de Judá, Naassom filho de Aminadabe:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 4, 'Seu exército, com os contados deles, setenta e quatro mil e seiscentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 5, 'Junto a ele acamparão os da tribo de Issacar: e o chefe dos filhos de Issacar, Natanael filho de Zuar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 6, 'E seu exército, com seus contados, cinquenta e quatro mil e quatrocentos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 7, 'E a tribo de Zebulom: e o chefe dos filhos de Zebulom, Eliabe filho de Helom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 8, 'E seu exército, com seus contados, cinquenta e sete mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 9, 'Todos os contados no exército de Judá, cento e oitenta e seis mil e quatrocentos, por seus esquadrões, irão diante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 10, 'A bandeira do exército de Rúben ao sul, por seus esquadrões: e o chefe dos filhos de Rúben, Elizur filho de Sedeur;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 11, 'E seu exército, seus contados, quarenta e seis mil e quinhentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 12, 'E acamparão junto a ele os da tribo de Simeão: e o chefe dos filhos de Simeão, Selumiel filho de Zurisadai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 13, 'E seu exército, com os contados deles, cinquenta e nove mil e trezentos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 14, 'E a tribo de Gade: e o chefe dos filhos de Gade, Eliasafe filho de Reuel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 15, 'E seu exército, com os contados deles, quarenta e cinco mil seiscentos e cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 16, 'Todos os contados no exército de Rúben, cento cinquenta e um mil quatrocentos e cinquenta, por seus esquadrões, irão na segunda posição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 17, 'Logo irá o tabernáculo do testemunho, o acampamento dos levitas em meio dos exércitos: da maneira que assentam o acampamento, assim caminharão, cada um em seu lugar, junto a suas bandeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 18, 'A bandeira do exército de Efraim por seus esquadrões, ao ocidente: e o chefe dos filhos de Efraim, Elisama filho de Amiúde;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 19, 'E seu exército, com os contados deles, quarenta mil e quinhentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 20, 'Junto a ele estará a tribo de Manassés; e o chefe dos filhos de Manassés, Gamaliel filho de Pedazur;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 21, 'E seu exército, com os contados deles, trinta e dois mil e duzentos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 22, 'E a tribo de Benjamim: e o chefe dos filhos de Benjamim, Abidã filho de Gideoni;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 23, 'E seu exército, com os contados deles, trinta e cinco mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 24, 'Todos os contados no exército de Efraim, cento e oito mil e cem, por seus esquadrões, irão na terceira posição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 25, 'A bandeira do exército de Dã estará ao norte, por seus esquadrões: e o chefe dos filhos de Dã, Aiezer filho de Amisadai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 26, 'E seu exército, com os contados deles, sessenta e dois mil e setecentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 27, 'Junto a ele acamparão os da tribo de Aser: e o chefe dos filhos de Aser, Pagiel filho de Ocrã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 28, 'E seu exército, com os contados deles, quarenta e um mil e quinhentos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 29, 'E a tribo de Naftali: e o chefe dos filhos de Naftali, Aira filho de Enã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 30, 'E seu exército, com os contados deles, cinquenta e três mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 31, 'Todos os contados no exército de Dã, cento cinquenta e sete mil e seiscentos: irão os últimos atrás de suas bandeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 32, 'Estes são os contados dos filhos de Israel, pelas casas de seus pais: todos os contados por exércitos, por seus esquadrões, seiscentos três mil quinhentos e cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 33, 'Mas os levitas não foram contados entre os filhos de Israel; como o SENHOR o mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 2, 34, 'E fizeram os filhos de Israel conforme todas as coisas que o SENHOR mandou a Moisés; assim assentaram o acampamento por suas bandeiras, e assim marcharam cada um por suas famílias, segundo as casas de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 1, 'E estas são as gerações de Arão e de Moisés, desde que o SENHOR falou a Moisés no monte Sinai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 2, 'E estes são os nomes dos filhos de Arão: Nadabe o primogênito, e Abiú, Eleazar, e Itamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 3, 'Estes são os nomes dos filhos de Arão, sacerdotes ungidos; cujas mãos ele encheu para administrar o sacerdócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 4, 'Mas Nadabe e Abiú morreram diante do SENHOR, quando ofereceram fogo estranho diante do SENHOR, no deserto de Sinai: e não tiveram filhos: e Eleazar e Itamar exerceram o sacerdócio diante de Arão seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 5, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 6, 'Faze chegar à tribo de Levi, e faze-a estar diante do sacerdote Arão, para que lhe ministrem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 7, 'E desempenhem seu cargo, e o cargo de toda a congregação diante do tabernáculo do testemunho, para servir no ministério do tabernáculo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 8, 'E guardem todos os móveis do tabernáculo do testemunho, e o encarregado a eles dos filhos de Israel, e ministrem no serviço do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 9, 'E darás os levitas a Arão e a seus filhos: são inteiramente dados a eles dentre os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 10, 'E constituirás a Arão e a seus filhos, para que exerçam seu sacerdócio: e o estranho que se chegar, morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 11, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 12, 'E eis que eu tomei os levitas dentre os filhos de Israel em lugar de todos os primogênitos que abrem a madre entre os filhos de Israel; serão, pois, meus os levitas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 13, 'Porque meu é todo primogênito; desde o dia que eu matei todos os primogênitos na terra do Egito, eu santifiquei a mim todos os primogênitos em Israel, tanto de homens como de animais; meus serão; Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 14, 'E o SENHOR falou a Moisés no deserto de Sinai, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 15, 'Conta os filhos de Levi pelas casas de seus pais, por suas famílias: contarás todos os homens de um mês acima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 16, 'E Moisés os contou conforme a palavra do SENHOR, como lhe foi mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 17, 'E os filhos de Levi foram estes por seus nomes: Gérson, e Coate, e Merari.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 18, 'E os nomes dos filhos de Gérson, por suas famílias, estes: Libni, e Simei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 19, 'E os filhos de Coate, por suas famílias: Anrão, e Izar, e Hebrom, e Uziel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 20, 'E os filhos de Merari, por suas famílias: Mali, e Musi. Estas, as famílias de Levi, pelas casas de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 21, 'De Gérson, a família de Libni e a de Simei: estas são as famílias de Gérson.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 22, 'Os contados deles conforme a conta de todos os homens de um mês acima, os contados deles, sete mil e quinhentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 23, 'As famílias de Gérson assentarão suas tendas à retaguarda do tabernáculo, ao ocidente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 24, 'E o chefe da casa do pai dos gersonitas, Eliasafe filho de Lael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 25, 'A cargo dos filhos de Gérson, no tabernáculo do testemunho, estará o tabernáculo, e a tenda, e sua cobertura, e a cortina da porta do tabernáculo do testemunho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 26, 'E as cortinas do átrio, e a cortina da porta do átrio, que está junto ao tabernáculo e junto ao altar ao redor; também suas cordas para todo seu serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 27, 'E de Coate, a família dos anramitas, e a família dos izaritas, e a família dos hebronitas, e a família dos uzielitas: estas são as famílias coatitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 28, 'Pela conta de todos os homens de um mês acima, eram oito mil e seiscentos, que tinham a guarda do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 29, 'As famílias dos filhos de Coate acamparão ao lado do tabernáculo, ao sul;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 30, 'E o chefe da casa do pai das famílias de Coate, Elisafã filho de Uziel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 31, 'E a cargo deles estará a arca, e a mesa, e o candelabro, e os altares, e os utensílios do santuário com que ministram, e o véu, com todo seu serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 32, 'E o principal dos chefes dos levitas será Eleazar, filho de Arão o sacerdote, supervisor dos que têm a guarda do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 33, 'De Merari, a família dos malitas e a família dos musitas: estas são as famílias de Merari.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 34, 'E os contados deles conforme a conta de todos os homens de um mês acima, foram seis mil e duzentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 35, 'E o chefe da casa do pai das famílias de Merari, Zuriel filho de Abiail: acamparão ao lado do tabernáculo, ao norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 36, 'E a cargo dos filhos de Merari estará a custódia das tábuas do tabernáculo, e suas barras, e suas colunas, e suas bases, e todos os seus utensílios, com todo seu serviço:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 37, 'E as colunas em derredor do átrio, e suas bases, e suas estacas, e suas cordas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 38, 'E os que acamparão diante do tabernáculo ao oriente, diante do tabernáculo do testemunho ao levante, serão Moisés, e Arão e seus filhos, tendo a guarda do santuário em lugar dos filhos de Israel: e o estranho que se aproximar, morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 39, 'Todos os contados dos levitas, que Moisés e Arão conforme a palavra do SENHOR contaram por suas famílias, todos os homens de um mês acima, foram vinte e dois mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 40, 'E o SENHOR disse a Moisés: Conta todos os primogênitos homens dos filhos de Israel de um mês acima, e toma a conta dos nomes deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 41, 'E tomarás os levitas para mim, eu o SENHOR, em lugar de todos os primogênitos dos filhos de Israel: e os animais dos levitas em lugar de todos os primogênitos dos animais dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 42, 'E contou Moisés, como o SENHOR lhe mandou, todos os primogênitos dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 43, 'E todos os primogênitos homens, conforme a conta dos nomes, de um mês acima, os contados deles foram vinte e dois mil duzentos setenta e três.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 44, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 45, 'Toma os levitas em lugar de todos os primogênitos dos filhos de Israel, e os animais dos levitas em lugar de seus animais; e os levitas serão meus: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 46, 'E pelos resgates dos duzentos e setenta e três, que excedem aos levitas os primogênitos dos filhos de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 47, 'Tomarás cinco siclos por cabeça; conforme o siclo do santuário tomarás: o siclo tem vinte óbolos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 48, 'E darás a Arão e a seus filhos o dinheiro pelos resgates dos que deles sobram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 49, 'Tomou, pois, Moisés o dinheiro do resgate dos que resultaram a mais dos resgatados pelos levitas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 50, 'E recebeu dos primogênitos dos filhos de Israel em dinheiro, mil trezentos sessenta e cinco siclos, conforme o siclo do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 3, 51, 'E Moisés deu o dinheiro dos resgates a Arão e a seus filhos, conforme o dito do SENHOR, segundo que o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 2, 'Toma a conta dos filhos de Coate dentre os filhos de Levi, por suas famílias, pelas casas de seus pais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 3, 'De idade de trinta anos acima até cinquenta anos, todos os que entram em companhia, para fazer serviço no tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 4, 'Este será o ofício dos filhos de Coate no tabernáculo do testemunho, no lugar santíssimo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 5, 'Quando se houver de mudar o acampamento, virão Arão e seus filhos, e desarmarão o véu da tenda, e cobrirão com ele a arca do testemunho:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 6, 'E porão sobre ela a coberta de peles finas, e estenderão encima o pano todo de azul, e lhe porão suas varas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 7, 'E sobre a mesa da proposição estenderão o pano azul, e porão sobre ela os pratos, e as colheres, e os copos, e as taças para fazer libações: e o pão contínuo estará sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 8, 'E estenderão sobre ela o pano de carmesim colorido, e o cobrirão com a coberta de peles finas; e lhe porão suas varas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 9, 'E tomarão um pano azul, e cobrirão o candelabro da luminária; e suas lâmpadas, e suas tenazes, e seus apagadores, e todos os seus vasos do azeite com que se serve;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 10, 'E o porão com todos os seus utensílios em uma coberta de peles finos, e o colocarão sobre umas armações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 11, 'E sobre o altar de ouro estenderão o pano azul, e lhe cobrirão com a coberta de peles finas, e lhe porão suas varas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 12, 'E tomarão todos os vasos do serviço, de que fazem uso no santuário, e os porão em um pano azul, e os cobrirão com uma coberta de peles finas, e os colocarão sobre umas armações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 13, 'E tirarão a cinza do altar, e estenderão sobre ele um pano de púrpura:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 14, 'E porão sobre ele todos os seus instrumentos de que se serve: as pás, os garfos, os braseiros, e as taças, todos os utensílios do altar; e estenderão sobre ele o propiciatório de peles finas, e lhe porão também as varas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 15, 'E em acabando Arão e seus filhos de cobrir o santuário e todos os vasos do santuário, quando o acampamento se houver de mudar, virão depois disso os filhos de Coate para conduzir: mas não tocarão coisa santa, que morrerão. Estas serão as cargas dos filhos de Coate no tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 16, 'Porém ao cargo de Eleazar, filho de Arão o sacerdote, estará o azeite da luminária, e o incenso aromático, e a oferta de cereais contínua, e o azeite da unção; o cargo de todo o tabernáculo, e de tudo o que está nele, no santuário, e em seus utensílios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 17, 'E falou o SENHOR a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 18, 'Não cortareis a tribo das famílias de Coate dentre os levitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 19, 'Mas isto fareis com eles, para que vivam, e não morram quando achegarem ao lugar santíssimo: Arão e seus filhos virão e os porão a cada um em seu ofício, e em seu cargo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 20, 'Não entrarão para ver, quando cobrirem as coisas santas; que morrerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 21, 'E falou o SENHOR a Moisés dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 22, 'Toma também a conta dos filhos de Gérson pelas casas de seus pais, por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 23, 'De idade de trinta anos acima até cinquenta anos os contarás; todos os que entram em companhia, para fazer serviço no tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 24, 'Este será o ofício das famílias de Gérson, para ministrar e para levar:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 25, 'Levarão as cortinas do tabernáculo, e o tabernáculo do testemunho, sua coberta, e a coberta de peles finas que está sobre ele encima, e a cortina da porta do tabernáculo do testemunho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 26, 'E as cortinas do átrio, e a cortina da porta do átrio, que está próxima do tabernáculo e próxima do altar ao redor, e suas cordas, e todos os instrumentos de seu serviço, e tudo o que será feito para eles: assim servirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 27, 'Segundo a ordem de Arão e de seus filhos será todo o ministério dos filhos de Gérson em todos os seus cargas, e em todo o seu serviço: e lhes atribuireis em responsabilidade todas as suas cargas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 28, 'Este é o serviço das famílias dos filhos de Gérson no tabernáculo do testemunho: e a responsabilidade deles estará sob a mão de Itamar, filho de Arão o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 29, 'Contarás os filhos de Merari por suas famílias, pelas casas de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 30, 'Desde o de idade de trinta anos acima até o de cinquenta anos, os contarás; todos os que entram em companhia, para fazer serviço no tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 31, 'E este será o dever de seu cargo para todo seu serviço no tabernáculo do testemunho: as tábuas do tabernáculo, e suas barras, e suas colunas, e suas bases,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 32, 'E as colunas do átrio ao redor, e suas bases, e suas estacas, e suas cordas com todos os seus instrumentos, e todo seu serviço; e contareis por seus nomes todos os vasos da guarda de seu cargo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 33, 'Este será o serviço das famílias dos filhos de Merari para todo seu ministério no tabernáculo do testemunho, sob a mão de Itamar, filho de Arão o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 34, 'Moisés, pois, e Arão, e os chefes da congregação, contaram os filhos de Coate por suas famílias, e pelas casas de seus pais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 35, 'Desde o de idade de trinta anos acima até o de idade de cinquenta anos; todos os que entram em companhia, para ministrar no tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 36, 'E foram os contados deles por suas famílias, dois mil setecentos e cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 37, 'Estes foram os contados das famílias de Coate, todos os que ministram no tabernáculo do testemunho, os quais contaram Moisés e Arão, como o mandou o SENHOR por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 38, 'E os contados dos filhos de Gérson, por suas famílias, e pelas casas de seus pais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 39, 'Desde o de idade de trinta anos acima até o de idade de cinquenta anos, todos os que entram em companhia, para ministrar no tabernáculo do testemunho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 40, 'Os contados deles por suas famílias, pelas casas de seus pais, foram dois mil seiscentos e trinta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 41, 'Estes são os contados das famílias dos filhos de Gérson, todos os que ministram no tabernáculo do testemunho, os quais contaram Moisés e Arão por ordem do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 42, 'E os contados das famílias dos filhos de Merari, por suas famílias, pelas casas de seus pais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 43, 'Desde o de idade de trinta anos acima até o de idade de cinquenta anos, todos os que entram em companhia, para ministrar no tabernáculo do testemunho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 44, 'Os contados deles, por suas famílias, foram três mil e duzentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 45, 'Estes foram os contados das famílias dos filhos de Merari, os quais contaram Moisés e Arão, segundo o mandou o SENHOR por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 46, 'Todos os contados dos levitas, que Moisés e Arão e os chefes de Israel contaram por suas famílias, e pelas casas de seus pais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 47, 'Desde o de idade de trinta anos acima até o de idade de cinquenta anos, todos os que entravam para ministrar no serviço, e ter cargo de obra no tabernáculo do testemunho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 48, 'Os contados deles foram oito mil quinhentos e oitenta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 4, 49, 'Como o mandou o SENHOR por meio de Moisés foram contados, cada um segundo seu ofício, e segundo seu cargo; os quais contou ele, como lhe foi mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 1, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 2, 'Manda aos filhos de Israel que expulsem do acampamento a todo leproso, e a todos os que sofrem de corrimento, e a todo contaminado sobre morto:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 3, 'Tanto homens como mulheres lançareis, fora do acampamento os expulsareis; para que não contaminem o acampamento daqueles entre os quais eu habito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 4, 'E fizeram-no assim os filhos de Israel, que os lançaram fora do acampamento: como o SENHOR disse a Moisés, assim o fizeram os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 5, 'Também falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 6, 'Fala aos filhos de Israel: O homem ou a mulher que cometer algum de todos os pecados dos homens, fazendo transgressão contra o SENHOR, e transgredir aquela pessoa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 7, 'Confessarão seu pecado que cometeram, e compensarão sua ofensa inteiramente, e acrescentarão seu quinto sobre ele, e o darão a aquele contra quem pecaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 8, 'E se aquele homem não tiver parente ao qual seja ressarcida a ofensa, se dará a indenização da injustiça ao SENHOR, ao sacerdote, a mais do carneiro das expiações, com o qual fará expiação por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 9, 'E toda oferta de todas as coisas santas que os filhos de Israel apresentarem ao sacerdote, sua será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 10, 'E o santificado de qualquer um será seu: também o que qualquer um der ao sacerdote, seu será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 11, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 12, 'Fala aos filhos de Israel, e dize-lhes: Quando a mulher de alguém se desviar, e fizer traição contra ele,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 13, 'Que alguém se houver deitado com ela em carnal ajuntamento, e seu marido não o houvesse visto por haver-se ela contaminado ocultamente, nem houver testemunha contra ela, nem ela houver sido pega no ato;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 14, 'Se vier sobre ele espírito de ciúme, e tiver ciúme de sua mulher, havendo-se ela contaminado; ou vier sobre ele espírito de ciúme, e tiver ciúmes de sua mulher, não havendo ela se contaminado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 15, 'Então o marido trará sua mulher ao sacerdote, e trará sua oferta com ela, um décimo de um efa de farinha de cevada; não lançará sobre ela azeite, nem porá sobre ela incenso; porque é oferta de ciúme, oferta de recordação, que traz o pecado em memória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 16, 'E o sacerdote a fará aproximar, e a porá diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 17, 'Logo tomará o sacerdote da água santa em um vaso de barro: tomará também o sacerdote do pó que houver no chão do tabernáculo, e o lançará na água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 18, 'E fará o sacerdote estar em pé à mulher diante do SENHOR, e descobrirá a cabeça da mulher, e porá sobre suas mãos a oferta da recordação, que é a oferta de ciúme; e o sacerdote terá na mão as águas amargas que trazem maldição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 19, 'E o sacerdote a fará jurar, e lhe dirá: Se ninguém houver dormido contigo, e se não te afastaste de teu marido à imundícia, livre sejas destas águas amargas que trazem maldição:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 20, 'Mas se te desviaste de teu marido, e te contaminaste, e alguém houver tido relação contigo, fora de teu marido:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 21, '(O sacerdote fará jurar à mulher com juramento de maldição, e dirá à mulher): O SENHOR te dê em maldição e em conspiração em meio de teu povo, fazendo o SENHOR a tua coxa que caia, e a teu ventre que se te inche;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 22, 'E estas águas que dão maldição entrem em tuas entranhas, e façam inchar teu ventre, e cair tua coxa. E a mulher dirá: Amém, Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 23, 'E o sacerdote escreverá estas maldições em um livro, e as apagará com as águas amargas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 24, 'E dará a beber à mulher as águas amargas que trazem maldição; e as águas que operam maldição entrarão nela por amargas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 25, 'Depois tomará o sacerdote da mão da mulher a oferta de ciúme, e a moverá diante do SENHOR, e a oferecerá diante do altar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 26, 'e o sacerdote tomará um punhado da oferta em sua memória, e o queimará sobre o altar, e depois dará a beber as águas à mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 27, 'Dará a ela pois a beber as águas; e será, que se for imunda e houver feito traição contra seu marido, as águas que operam maldição entrarão nela em amargura, e seu ventre se inchará, e cairá sua coxa; e a mulher será por maldição em meio de seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 28, 'Mas se a mulher não for imunda, mas sim que estiver limpa, ela será livre, e será fértil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 29, 'Esta é a lei do ciúme, quando a mulher fizer traição a seu marido, e se contaminar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 30, 'Ou do marido, sobre o qual passar espírito de ciúme, e tiver ciúme de sua mulher: ele a apresentará então diante do SENHOR, e o sacerdote executará nela toda esta lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 5, 31, 'E aquele homem será livre de iniquidade, e a mulher levará seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 2, 'Fala aos filhos de Israel, e dize-lhes: O homem, ou a mulher, quando se separar fazendo voto de nazireu, para dedicar-se ao SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 3, 'Se absterá de vinho e de bebida forte; vinagre de vinho, nem vinagre de bebida forte não beberá, nem beberá algum licor de uvas, nem tampouco comerá uvas frescas nem secas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 4, 'Todo o tempo de seu nazireado, de tudo o que se faz de vide de vinho, desde os caroços até a casca, não comerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 5, 'Todo o tempo do voto de seu nazireado não passará navalha sobre sua cabeça, até que sejam cumpridos os dias de sua separação ao SENHOR: santo será; deixará crescer as pontas do cabelo de sua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 6, 'Todo o tempo que se separar ao SENHOR, não entrará a pessoa morta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 7, 'Por seu pai, nem por sua mãe, por seu irmão, nem por sua irmã, não se contaminará com eles quando morrerem; porque consagração de seu Deus tem sobre sua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 8, 'Todo o tempo de seu nazireado, será santo ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 9, 'E se alguém morrer muito de repente junto a ele, contaminará a cabeça de seu nazireado; portanto o dia de sua purificação rapará sua cabeça; ao sétimo dia a rapará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 10, 'E o dia oitavo trará duas rolinhas ou dois pombinhos ao sacerdote, à porta do tabernáculo do testemunho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 11, 'E o sacerdote fará um em expiação, e o outro em holocausto: e o expiará do que pecou sobre o morto, e santificará sua cabeça naquele dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 12, 'E consagrará ao SENHOR os dias de seu nazireado, e trará um cordeiro de ano em expiação pela culpa; e os dias primeiros serão anulados, porquanto foi contaminado seu nazireado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 13, 'Esta é, pois, a lei do nazireu no dia que se cumprir o tempo de seu nazireado: Virá à porta do tabernáculo do testemunho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 14, 'E oferecerá sua oferta ao SENHOR, um cordeiro de ano sem mácula em holocausto, e uma cordeira de ano sem defeito em expiação, e um carneiro sem defeito por sacrifício pacífico:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 15, 'Além disso um cesto de pães ázimos, tortas de boa farinha amassadas com azeite, e massas não fermentadas untadas com azeite, e sua oferta de cereais, e suas libações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 16, 'E o sacerdote o oferecerá diante do SENHOR, e fará sua expiação e seu holocausto:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 17, 'E oferecerá o carneiro em sacrifício pacífico ao SENHOR, com o cesto dos pães ázimos; oferecerá também o sacerdote sua oferta de cereais, e suas libações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 18, 'Então o nazireu rapará à porta do tabernáculo do testemunho a cabeça de seu nazireado, e tomará os cabelos da cabeça de seu nazireado, e os porá sobre o fogo que está debaixo do sacrifício pacífico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 19, 'Depois tomará o sacerdote a coxa cozida do carneiro, e uma torta sem levedura do cesto, e uma massa sem levedura, e as porá sobre as mãos do nazireu, depois que for estragado seu nazireado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 20, 'E o sacerdote moverá aquilo, oferta movida diante do SENHOR; o qual será coisa santa do sacerdote, a mais do peito movido e da coxa separada: e depois poderá beber vinho o nazireu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 21, 'Esta é a lei do nazireu que fizer voto de sua oferta ao SENHOR por seu nazireado, a mais do que sua mão alcançar: segundo o voto que fizer, assim fará, conforme a lei de seu nazireado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 22, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 23, 'Fala a Arão e a seus filhos, e dize-lhes: Assim abençoareis aos filhos de Israel, dizendo-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 24, 'O SENHOR te abençoe, e te guarde:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 25, 'Faça resplandecer o SENHOR seu rosto sobre ti, e tenha de ti misericórdia:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 26, 'O SENHOR levante a ti seu rosto, e ponha em ti paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 6, 27, 'E porão meu nome sobre os filhos de Israel, e eu os abençoarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 1, 'E aconteceu, que quando Moisés acabou de levantar o tabernáculo, e o ungido, e o santificado, com todos os seus utensílios; e também ungido e santificado o altar, com todos os seus utensílios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 2, 'Então os príncipes de Israel, os chefes das casas de seus pais, os quais eram os príncipes das tribos, que estavam sobre os contados, ofereceram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 3, 'E trouxeram suas ofertas diante do SENHOR, seis carros cobertos, e doze bois; por cada dois príncipes um carro, e cada um deles um boi; o qual ofereceram diante do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 4, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 5, 'Toma-o deles, e será para o serviço do tabernáculo do testemunho: e o darás aos levitas, a cada um conforme seu ministério.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 6, 'Então Moisés recebeu os carros e os bois, e deu-os aos levitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 7, 'Dois carros e quatro bois, deu aos filhos de Gérson, conforme seu ministério;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 8, 'E aos filhos de Merari deu os quatro carros e oito bois, conforme seu ministério, sob a mão de Itamar, filho de Arão o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 9, 'E aos filhos de Coate não deu; porque levavam sobre si nos ombros o serviço do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 10, 'E ofereceram os príncipes à dedicação do altar o dia que foi ungido, ofereceram os príncipes sua oferta diante do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 11, 'E o SENHOR disse a Moisés: Oferecerão sua oferta, um príncipe um dia, e outro príncipe outro dia, à dedicação do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 12, 'E o que ofereceu sua oferta o primeiro dia foi Naassom filho de Aminadabe, da tribo de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 13, 'E foi sua oferta um prato de prata de peso de cento e trinta siclos, e uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de boa farinha amassada com azeite para oferta de cereais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 14, 'Uma colher de ouro de dez siclos, cheia de incenso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 15, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 16, 'Um bode macho para expiação;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 17, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Naassom, filho de Aminadabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 18, 'No segundo dia ofereceu Natanael filho de Zuar, príncipe de Issacar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 19, 'Ofereceu por sua oferta um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de boa farinha amassada com azeite para oferta de cereais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 20, 'Uma colher de ouro de dez siclos, cheia de incenso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 21, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 22, 'Um bode macho para expiação;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 23, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Natanael, filho de Zuar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 24, 'No terceiro dia, Eliabe filho de Helom, príncipe dos filhos de Zebulom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 25, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de boa farinha amassada com azeite para oferta de cereais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 7, 26, 'Uma colher de ouro de dez siclos, cheia de incenso;'),
